		origin: new options._catchError._ChildOrigin(
			isNode ? childVNode._original : childVNode,
			index
		),
		treeLinks: new options._catchError._ChildTreeLinks(
			isNode ? childVNode._depth : 0,
			isNode ? childVNode.type : null,
			parentVNode
		),
		content: new ChildContent(childVNode, isNode ? childVNode.props : undefined)
	};
}

